 project={'slug':slug,'title':title,'format':{'type':'youtube-shorts','width':1080,'height':1920,'fps':60},'video':{'width':1080,'height':1920,'fps':60},'status':'production-active','currentRevision':REV,'currentFinalDirectory':'production/local/final-reviewed','authorization':auth,'paths':{'script':f'projects/{slug}/script/narration.spoken.ko.json','checkpoint':f'projects/{slug}/production/checkpoint.json','productionPlan':f'projects/{slug}/planning/production-plan.json'},'publishReady':False}
